/**
 * fonts.css is generated by scripts/fonts/build-fonts.py (never hand-edited): these checks pin
 * the slicing contract the shell relies on — the UI glyph inventory (∪ EXTRA_UI) lives in `base`,
 * the brush family ships no catch-all `rest` face, Yuji Syuku and Shippori Mincho B1 end with a
 * `shell` face declared after `base` (design 09 §3.5), the Dojo's first paint stays under the
 * 07 §9 budget measured from the files on disk — and the glyphs the home screen actually sets in
 * brush and Mincho (the strings files, public/calendar/koyomi.json) are inside the two shells, so
 * that sum is real rather than a paper number — and every slice file on disk is one the
 * stylesheet uses — and, since the CSS fence cannot see a class applied in TSX, that no .tsx in the fenced
 * directories mounts the `.mincho` / `.neon` utility classes. The glyph lists that carry 09 §3.5's additions are written as \u escapes
 * (this file is outside the inventory walk, but no kanji should enter src by way of a test).
 */
const ROOT = process.cwd();
const css = readFileSync(resolve(ROOT, 'src/styles/fonts.css'), 'utf8');

interface Face {
  family: string;
  file: string;
  range: string;
}
type Span = [lo: number, hi: number];

const faces: Face[] = Array.from(css.matchAll(/@font-face \{([^}]*)\}/g), (m) => {
  const body = m[1]!;
  return {
    family: /font-family: "([^"]+)"/.exec(body)![1]!,
    file: /url\("\/fonts\/([^"]+)"\)/.exec(body)![1]!,
    range: /unicode-range: ([^;]+);/.exec(body)![1]!,
  };
});

const FAMILIES = ['DotGothic16', 'Yuji Syuku', 'Shippori Mincho B1', 'Dela Gothic One'];
const STEM: Record<string, string> = { DotGothic16: 'DotGothic16', 'Yuji Syuku': 'YujiSyuku', 'Shippori Mincho B1': 'ShipporiMinchoB1', 'Dela Gothic One': 'DelaGothicOne' };
/** The two families with a `shell` face (09 §3.5): brush for the brand and the Road, mincho for the Dojo column. */
const SHELL_FAMILIES = ['Yuji Syuku', 'Shippori Mincho B1'];
/** Design 09 quotes decimal kilobytes (DotGothic16-base "54 KB" = 53 748 bytes); the stricter reading of every budget. */
const KB = 1000;
const SLICE_RE = /-(rest|n2|n3|n4|n5|base|shell)\.woff2$/;
const slice = (file: string): string => {
  const m = SLICE_RE.exec(file);
  if (!m) throw new Error(`unknown slice in ${file}`);
  return m[1]!;
};
const isLevel = (f: Face): boolean => /^n[2-5]$/.test(slice(f.file));
const byFamily = (family: string): Face[] => faces.filter((f) => f.family === family);
/** The face named `base` — not "the last one": `shell` is declared after it (09 §3.5). */
const baseOf = (family: string): Face => {
  const f = byFamily(family).find((x) => slice(x.file) === 'base');
  if (!f) throw new Error(`${family}: no base face`);
  return f;
};
const shellOf = (family: string): Face | undefined => byFamily(family).find((x) => slice(x.file) === 'shell');
const spans = (range: string): Span[] =>
  range.split(',').map((part) => {
    const m = /U\+([0-9A-F]+)(?:-([0-9A-F]+))?/i.exec(part.trim());
    if (!m) throw new Error(`bad unicode-range item: ${part}`);
    const lo = parseInt(m[1]!, 16);
    return [lo, m[2] ? parseInt(m[2], 16) : lo];
  });
const covers = (sp: Span[], cp: number): boolean => sp.some(([lo, hi]) => lo <= cp && cp <= hi);
const isCjk = (cp: number): boolean => (cp >= 0x4e00 && cp <= 0x9fff) || (cp >= 0x3400 && cp <= 0x4dbf) || (cp >= 0xf900 && cp <= 0xfaff);
const glyphs = (cps: Iterable<number>): string => Array.from(cps, (cp) => String.fromCodePoint(cp)).join('');
/** Every printable code point of the strings (kanji, kana, ヶ…), as a set. */
const codePoints = (...texts: string[]): Set<number> => {
  const out = new Set<number>();
  for (const ch of texts.join('')) {
    const cp = ch.codePointAt(0)!;
    if (cp > 0x20 && !/\s/.test(ch)) out.add(cp);
  }
  return out;
};
const bytes = (file: string): number => statSync(resolve(ROOT, 'public/fonts', file)).size;
const relPath = (p: string): string => relative(ROOT, p).split(sep).join('/');

/* ── the UI glyph inventory, mirrored from UI_SOURCES / UI_EXCLUDE in scripts/fonts/build-fonts.py ── */
const UI_EXCLUDE = ['.test.', 'src/content/fixtures/', 'src/art/wallpapers/kanji-stars.ts'];

function walk(dir: string, out: string[] = []): string[] {
  for (const name of readdirSync(dir)) {
    if (name === 'node_modules' || name.startsWith('.')) continue;
    const full = join(dir, name);
    if (statSync(full).isDirectory()) walk(full, out);
    else out.push(full);
  }
  return out;
}

const uiFiles = [...walk(resolve(ROOT, 'src')).filter((p) => /\.(ts|tsx|css)$/.test(p)), resolve(ROOT, 'index.html'), resolve(ROOT, 'public/manifest.webmanifest')].filter(
  (p) => !UI_EXCLUDE.some((x) => relPath(p).includes(x)),
);
const uiKanji = new Set<number>();
for (const p of uiFiles) {
  for (const ch of readFileSync(p, 'utf8')) {
    const cp = ch.codePointAt(0)!;
    if (isCjk(cp)) uiKanji.add(cp);
  }
}

