interface CssRule {
  file: string;
  selector: string;
  decls: string;
}

/** A small static CSS walk: every selector with the declarations it owns (nested blocks, at-rule wrappers and nested at-rules unwrapped; comments stripped). */
function cssRulesFromText(file: string, source: string): CssRule[] {
  const text = source.replace(/\/\*[\s\S]*?\*\//g, '');
  const out: CssRule[] = [];
  const stack: string[] = [];
  const parent = (): string => [...stack].reverse().find((s) => !s.startsWith('@')) ?? '';
  let start = 0;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '{') {
      const seg = text.slice(start, i);
      const k = seg.lastIndexOf(';');
      if (k >= 0 && stack.length) out.push({ file, selector: parent(), decls: seg.slice(0, k + 1) }); // declarations before a nested block
      const prelude = seg.slice(k + 1).trim();
      stack.push(prelude.includes('&') ? prelude.replace(/&/g, parent()) : prelude);
      start = i + 1;
    } else if (ch === '}') {
      const popped = stack.pop() ?? '';
      // a nested at-rule (`.x { @media (…) { … } }`) owns no selector: its declarations are the enclosing selector's
      out.push({ file, selector: popped.startsWith('@') ? parent() : popped, decls: text.slice(start, i) });
      start = i + 1;
    }
  }
  return out.filter((r) => r.selector && !r.selector.startsWith('@'));
}
const cssRules = (file: string): CssRule[] => cssRulesFromText(file, readFileSync(file, 'utf8'));

function fontFence(): { files: string[]; offenders: string[]; used: Set<string> } {
  const files = FONT_FENCE_DIRS.flatMap((d) => walk(resolve(ROOT, d))).filter((p) => p.endsWith('.css'));
  const offenders: string[] = [];
  const used = new Set<string>();
  for (const file of files) {
    for (const r of cssRules(file)) {
      if (!FONT_FENCE_RE.test(r.decls)) continue;
      for (const sel of splitSelectorList(r.selector)) {
        if (SHELL_COVERED.test(lastCompound(sel))) continue;
        if (sel in FONT_FENCE_ALLOW_LANDED || sel in FONT_FENCE_ALLOW_PLANNED) {
          used.add(sel);
          continue;
        }
        offenders.push(`${relPath(file)} → ${sel}`);
      }
    }
  }
  return { files, offenders, used };
}

/* ── the same fence for TSX: a utility class is a declaration the CSS walk cannot see. PrintFigure.tsx's hero title
 * wore `.mincho` for a day, and the manifest's title glyphs — outside every shell slice — pulled ShipporiMinchoB1-base,
 * `rest` and the level slices (238–830 KB a day, docs/ART_PACK.md §9) onto the Dojo's first paint while this file
 * stayed green. Every whitespace-separated word inside a string or template literal counts, class or not: the fence
 * over-approximates by design, and `[lang="ja"]` / `--font-ja` is the answer either way. ── */
const CLASS_FENCE_RE = /^(mincho|neon)$/;
/** The words a .tsx could mount as classes: string and template literals (`${…}` holes blanked), comments stripped first. */
function literalTokens(source: string): string[] {
  const text = source.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[ \t])\/\/[^\n]*/gm, '$1');
  const out: string[] = [];
  for (const m of text.matchAll(/"((?:[^"\\\n]|\\.)*)"|'((?:[^'\\\n]|\\.)*)'|`((?:[^`\\]|\\.)*)`/g)) {
    for (const tok of (m[1] ?? m[2] ?? m[3] ?? '').replace(/\$\{[^}]*\}/g, ' ').split(/\s+/)) if (tok) out.push(tok);
  }
  return out;
}
function classFence(): { files: string[]; offenders: string[] } {
  const files = FONT_FENCE_DIRS.flatMap((d) => walk(resolve(ROOT, d))).filter((p) => p.endsWith('.tsx') && !p.includes('.test.'));
  const offenders: string[] = [];
  for (const file of files) for (const tok of literalTokens(readFileSync(file, 'utf8'))) if (CLASS_FENCE_RE.test(tok)) offenders.push(`${relPath(file)} → .${tok}`);
  return { files, offenders };
}

describe('fonts.css slices', () => {
  it('declares the four families, each with base + the four JLPT level slices', () => {
    for (const family of FAMILIES) {
      const slices = byFamily(family).map((f) => slice(f.file));
      expect(slices, family).toEqual(expect.arrayContaining(['base', 'n5', 'n4', 'n3', 'n2']));
    }
  });

  it('the brush family (Yuji Syuku) ships no catch-all `rest` face: shell chrome and proper names never pull 815 KB of non-corpus kanji', () => {
    const yuji = byFamily('Yuji Syuku');
    expect(yuji.some((f) => slice(f.file) === 'rest')).toBe(false);
    expect(yuji.some((f) => f.range.includes('U+4E00-9FFF'))).toBe(false);
  });

  it('where a `rest` face exists it is declared first (lowest precedence), the level slices use explicit code points, and `base` follows every level slice', () => {
    for (const family of ['DotGothic16', 'Shippori Mincho B1', 'Dela Gothic One']) {
      const list = byFamily(family);
      expect(slice(list[0]!.file), family).toBe('rest');
      const baseAt = list.indexOf(baseOf(family));
      for (const f of list.filter(isLevel)) {
        expect(f.range, f.file).not.toMatch(/U\+4E00-9FFF/);
        expect(list.indexOf(f), `${f.file} must be declared before base`).toBeLessThan(baseAt);
      }
    }
  });

  it('`base` is declared after every level slice in every family — followed only by `shell` — and lists its code points explicitly beyond the kana / symbol blocks', () => {
    for (const family of FAMILIES) {
      const list = byFamily(family);
      const base = baseOf(family);
      const after = list.slice(list.indexOf(base) + 1).map((f) => slice(f.file));
      expect(after, `${family}: faces declared after base`).toEqual(SHELL_FAMILIES.includes(family) ? ['shell'] : []);
      expect(base.range, family).toMatch(/U\+3000-30FF/); // kana and CJK punctuation stay a block range
      expect(spans(base.range).filter(([lo]) => isCjk(lo)).length, family).toBeGreaterThan(100);
    }
  });

  it('the UI glyph inventory (every CJK ideograph in src/**, index.html and the manifest) ∪ EXTRA_UI sits in every family\'s `base` face and in no level slice', () => {
    expect(uiKanji.size).toBeGreaterThan(300); // strings files, STATIONS, belt / page / reward names
    expect(EXTRA_UI.size).toBe(13);
    const must = new Set([...uiKanji, ...EXTRA_UI]);
    for (const family of FAMILIES) {
      const base = spans(baseOf(family).range);
      const missing = [...must].filter((cp) => !covers(base, cp));
      expect(glyphs(missing), `${family} base lacks shell glyphs — rerun scripts/fonts/build-fonts.py`).toBe('');
      for (const f of byFamily(family).filter(isLevel)) {
        const level = spans(f.range);
        const leaked = [...must].filter((cp) => covers(level, cp));
        expect(glyphs(leaked), `${f.file} still carries shell glyphs — rerun scripts/fonts/build-fonts.py`).toBe('');
      }
    }
  });

  it('frozen: the inventory walk ∪ EXTRA_UI equals UI_KANJI_ALLOWED — no new UI kanji outside 09 §3.5\'s list (a test, not a request)', () => {
    expect(UI_KANJI_ALLOWED.size).toBe(550); // 537 landed + 13 EXTRA_UI
    const now = new Set([...uiKanji, ...EXTRA_UI]);
    const added = [...now].filter((cp) => !UI_KANJI_ALLOWED.has(cp)).sort((a, b) => a - b);
    const removed = [...UI_KANJI_ALLOWED].filter((cp) => !now.has(cp)).sort((a, b) => a - b);
    expect(glyphs(added), 'new UI kanji in src — 09 §10 house rule: none outside §3.5. Lead-approved? add them to UI_KANJI_ALLOWED and rerun scripts/fonts/build-fonts.py').toBe('');
    expect(glyphs(removed), 'UI kanji left src — drop them from UI_KANJI_ALLOWED and rerun scripts/fonts/build-fonts.py so every base matches').toBe('');
  });

  it('station names (STATIONS) and the nav glyphs 橋帯庫蔵録設 render from `base` alone', () => {
    const must = new Set<number>();
    for (const ch of ['橋帯庫蔵録設', ...STATIONS.flatMap((s) => [s.nameJa, s.gateJa])].join('')) {
      const cp = ch.codePointAt(0)!;
      if (isCjk(cp)) must.add(cp);
    }
    expect(must.has('鞠'.codePointAt(0)!)).toBe(true); // 鞠子 — a non-JLPT kanji that used to live in `rest`
    for (const family of FAMILIES) {
      const base = spans(baseOf(family).range);
      expect(glyphs([...must].filter((cp) => !covers(base, cp))), family).toBe('');
    }
  });

  it('every face has a local() fallback, format("woff2"), font-display: swap, a known slice name, and its slice file ships in public/fonts/', () => {
    const bodies = Array.from(css.matchAll(/@font-face \{([^}]*)\}/g), (m) => m[1]!);
    expect(bodies).toHaveLength(faces.length);
    for (const body of bodies) {
      expect(body).toMatch(/font-display: swap/);
      expect(body).toMatch(/src: local\("[^"]+"\), local\("[^"]+"\), url\("\/fonts\/[A-Za-z0-9]+-(rest|n2|n3|n4|n5|base|shell)\.woff2"\) format\("woff2"\)/);
    }
    for (const f of faces) expect(() => statSync(resolve(ROOT, 'public/fonts', f.file)), f.file).not.toThrow();
  });

  it('no orphan slice on disk: every public/fonts/*.woff2 is referenced by fonts.css (the dropped Yuji `rest` is gone; the two `shell` files are present and no other family has one)', () => {
    const referenced = new Set(faces.map((f) => f.file));
    const onDisk = readdirSync(resolve(ROOT, 'public/fonts')).filter((f) => f.endsWith('.woff2'));
    expect(onDisk.filter((f) => !referenced.has(f))).toEqual([]);
    expect(onDisk).not.toContain('YujiSyuku-rest.woff2');
    for (const family of FAMILIES) {
      expect(onDisk, family).toContain(`${STEM[family]}-base.woff2`);
      if (SHELL_FAMILIES.includes(family)) expect(onDisk, family).toContain(`${STEM[family]}-shell.woff2`);
      else expect(onDisk, family).not.toContain(`${STEM[family]}-shell.woff2`);
    }
  });
});

describe('shell faces (design 09 §3.5) and the first-paint budget (07 §9)', () => {
  it('Yuji Syuku and Shippori Mincho B1 — and only they — declare a `shell` face after `base`, as explicit code points that win the overlap', () => {
    for (const family of FAMILIES) {
      const list = byFamily(family);
      const shell = shellOf(family);
      if (!SHELL_FAMILIES.includes(family)) {
        expect(shell, `${family} has no shell`).toBeUndefined();
        continue;
      }
      expect(shell, family).toBeDefined();
      expect(list.indexOf(shell!), `${family}: shell is the last face`).toBe(list.length - 1);
      expect(list.indexOf(baseOf(family)), `${family}: base is declared right before shell`).toBe(list.length - 2);
      expect(shell!.range, family).not.toMatch(/U\+0000-00FF|U\+3000-30FF|U\+4E00-9FFF/); // never a block: base keeps those
      for (const [lo, hi] of spans(shell!.range)) expect(hi - lo, `${family} shell span U+${lo.toString(16)}`).toBeLessThan(8);
    }
  });

  it("YujiSyuku-shell.woff2 ≤ 60 KB and covers つづく, the belt names, Nihonbashi, the 53 STATIONS, Sanjō Ōhashi, ippon / kiai / rest, the five flame glyphs and the Dojo home's brush words", () => {
    expect(bytes('YujiSyuku-shell.woff2')).toBeLessThanOrEqual(60 * KB);
    expect(YUJI_SHELL.has(0x30f6), 'ヶ of Hodogaya is a kana-block glyph the shell must list explicitly').toBe(true);
    expect(YUJI_SHELL.has('鞠'.codePointAt(0)!)).toBe(true);
    expect(YUJI_SHELL.size).toBeGreaterThan(90);
    const sp = spans(shellOf('Yuji Syuku')!.range);
    expect(glyphs([...YUJI_SHELL].filter((cp) => !covers(sp, cp))), 'Yuji shell lacks — rerun scripts/fonts/build-fonts.py').toBe('');
    expect(DOJO_HOME_BRUSH.every((w) => w.length > 0)).toBe(true);
    expect(
      glyphs([...codePoints(...DOJO_HOME_BRUSH)].filter((cp) => !covers(sp, cp))),
      'a Dojo-home brush word is outside the Yuji shell — YujiSyuku-base would load on first paint; add its key to DOJO_BRUSH_KEYS / DOJO_HOME_BRUSH and rerun scripts/fonts/build-fonts.py',
    ).toBe('');
  });

  it('ShipporiMinchoB1-shell.woff2 ≤ 40 KB and covers the column: the 24 sekki, the sekki label, the ordinal frame with one to ten, the era date, the eight moon names, the omikuji heads', () => {
    expect(bytes('ShipporiMinchoB1-shell.woff2')).toBeLessThanOrEqual(40 * KB);
    expect(SEKKI).toHaveLength(24);
    expect(MOON).toHaveLength(8);
    for (const cp of EXTRA_UI) expect(SHIPPORI_SHELL.has(cp), `EXTRA_UI U+${cp.toString(16)} belongs to the column`).toBe(true);
    expect(SHIPPORI_SHELL.size).toBeGreaterThan(50);
    const sp = spans(shellOf('Shippori Mincho B1')!.range);
    expect(glyphs([...SHIPPORI_SHELL].filter((cp) => !covers(sp, cp))), 'Shippori shell lacks — rerun scripts/fonts/build-fonts.py').toBe('');
  });

  it.skipIf(!koyomi)("the column's data — every sekki and moon name in public/calendar/koyomi.json — is inside the Shippori shell, and the mirrored lists match it, so a respelling by A3 cannot quietly pull ShipporiMinchoB1-base", () => {
    const sekki = Object.values(koyomi!.sekki ?? {});
    const moon = Object.values(koyomi!.moon ?? {});
    expect(sekki).toHaveLength(24);
    expect(moon).toHaveLength(8);
    expect([...sekki].sort(), 'SEKKI mirrors koyomi.json /sekki — update the list here and in build-fonts.py').toEqual([...SEKKI].sort());
    expect([...moon].sort(), 'MOON mirrors koyomi.json /moon — update the list here and in build-fonts.py').toEqual([...MOON].sort());
    const sp = spans(shellOf('Shippori Mincho B1')!.range);
    expect(glyphs([...codePoints(...sekki, ...moon)].filter((cp) => isCjk(cp) && !covers(sp, cp))), 'koyomi.json names a glyph the Shippori shell lacks — rerun scripts/fonts/build-fonts.py').toBe('');
  });

  it('the real first paint — DotGothic16-base + YujiSyuku-shell + ShipporiMinchoB1-shell on disk — is ≤ 250 KB (07 §9; 09 §10 budgets table)', () => {
    const sum = bytes('DotGothic16-base.woff2') + bytes('YujiSyuku-shell.woff2') + bytes('ShipporiMinchoB1-shell.woff2');
    expect(sum).toBeLessThanOrEqual(250 * KB);
  });
});

describe('font fence (09 §10 A4): Mincho and Neon in shell-level CSS only on the shell-covered classes', () => {
  const fence = fontFence();

  it('walks src/styles/*.css, src/app/**/*.css, src/art/dojo/**/*.css and src/art/prints/**/*.css', () => {
    expect(fence.files.length).toBeGreaterThanOrEqual(9);
    expect(fence.files.some((p) => p.endsWith('src/styles/base.css'))).toBe(true);
    expect(fence.files.some((p) => p.endsWith('src/app/pages/pages.css'))).toBe(true);
    expect(fence.files.some((p) => p.endsWith('src/art/prints/PrintFigure.css'))).toBe(true);
  });

  it('no selector sets var(--font-mincho) or var(--font-neon) outside .tategaki-column / .sign__ordinal / .seal-date and the allow-list', () => {
    expect(fence.offenders, 'the Dojo first paint would pull a base slice — use --font-ja, or move the rule out of shell-level CSS').toEqual([]);
  });

  it('every landed allow-list entry is still in use (when the owner moves the use, they delete the entry)', () => {
    const stale = Object.keys(FONT_FENCE_ALLOW_LANDED).filter((sel) => !fence.used.has(sel));
    expect(stale, 'delete these FONT_FENCE_ALLOW_LANDED entries: the selector no longer sets Mincho / Neon').toEqual([]);
  });

  it("the static walk sees declarations before a nested block, resolves & against the parent, and gives a nested at-rule's declarations to the enclosing selector", () => {
    const sample =
      '.a { color: red; font-family: var(--font-mincho); &:hover { opacity: 1; } }\n@media (min-width: 1px) { .b, .c { font-family: var(--font-neon); } }\n.d { font-family: var(--font-ja); }\n.e { color: red; @media (min-width: 1px) { font-family: var(--font-mincho); } }';
    const rules = cssRulesFromText('x.css', sample);
    const hits = rules.filter((r) => FONT_FENCE_RE.test(r.decls)).map((r) => r.selector);
    expect(hits).toEqual(['.a', '.b, .c', '.e']);
    expect(rules.map((r) => r.selector)).toContain('.a:hover');
    expect(rules.map((r) => r.selector).some((s) => s.startsWith('@'))).toBe(false);
  });

  it('selector lists split only on top-level commas, and the shell-covered exemption looks at the last compound alone', () => {
    expect(splitSelectorList(':is(.p, .q) .r, .s')).toEqual([':is(.p, .q) .r', '.s']);
    expect(lastCompound('.tategaki-column .sentence')).toBe('.sentence');
    expect(lastCompound(':is(.a, .b) > .tategaki-column[data-face="mincho"]')).toBe('.tategaki-column[data-face="mincho"]');
    expect(SHELL_COVERED.test(lastCompound('.tategaki-column[data-face="mincho"]'))).toBe(true);
    expect(SHELL_COVERED.test(lastCompound('.sign .sign__ordinal'))).toBe(true);
    expect(SHELL_COVERED.test(lastCompound('.tategaki-column .sentence'))).toBe(false);
    expect(SHELL_COVERED.test(lastCompound('.seal-date__day'))).toBe(false);
  });

  it('no .tsx in the fenced directories mounts the .mincho or .neon utility class (the CSS walk cannot see a class applied in TSX: the prints hero title did — docs/ART_PACK.md §9)', () => {
    const classes = classFence();
    expect(classes.files.some((p) => p.endsWith('src/art/prints/PrintFigure.tsx'))).toBe(true);
    expect(classes.files.some((p) => p.endsWith('src/app/pages/DojoPage.tsx'))).toBe(true);
    expect(classes.files.some((p) => p.includes('.test.'))).toBe(false);
    expect(classes.offenders, 'a utility face on first-paint glyphs outside the shells — [lang="ja"] gives --font-ja for no bytes').toEqual([]);
  });

  it('the literal walk sees a class attribute, a template with holes and a class built in a const; it ignores comments and compound names, and keeps a URL whole', () => {
    const sample = '// brush/mincho text\n/* .neon in a comment */\nconst cls = `print ${variant} mincho`;\n<span class="print__title-ja neon-c" data-face={\'neon\'} />\n<a href="https://x.test/y" class={`a ${b} neon`} /> // trailing mincho';
    const toks = literalTokens(sample);
    expect(toks.filter((t) => CLASS_FENCE_RE.test(t))).toEqual(['mincho', 'neon', 'neon']);
    expect(toks).toContain('neon-c');
    expect(toks).toContain('https://x.test/y');
    expect(toks).not.toContain('text');
    expect(toks).not.toContain('trailing');
  });
});
